import{z as E,x as p,o as t,c as A,q as s,j as i,D as e,d as r,s as o,S as l,b as d}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"d 叉堆与索引堆","description":"","frontmatter":{"title":"d 叉堆与索引堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dary-heap.md","filePath":"cs/dary-heap.md","lastUpdated":1791063341000}'),B={name:"cs/dary-heap.md"};function c(h,a,m,D,u,T){const n=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="d-叉堆与索引堆" tabindex="-1">d 叉堆与索引堆 <a class="header-anchor" href="#d-叉堆与索引堆" aria-label="Permalink to &quot;d 叉堆与索引堆&quot;">​</a></h1><div class="epigraph"><p>每个节点 $d$ 个孩子，树更矮，下滤比较次数变多；再存从元素到下标的句柄，decrease-key 才不必先扫全表。</p><footer>—— 据 Johnson, Priority Queues with Update and Finding Minimum Spanning Trees, 1975；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/heap-priority">上一课</a>钉了二叉堆：完全树、数组下标 \\(2i,2i+1\\)、insert/extract-min 为 \\(\\Theta(\\log n)\\)，并声明 decrease-key 需要句柄、\\(d\\) 叉不在那一课。本课不重讲堆序。缺口是两个实现参数：扇出 \\(d\\) 改变高度与下滤代价；索引（句柄）让「已知元素降键」真正 \\(\\Theta(d\\log_d n)\\)。散列课马上要另一条 \\(O(1)\\) 期望查找，对象不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二叉下滤每层比两个孩子。\\(d\\) 叉：孩子是 \\(di+1,\\ldots,di+d\\)，高度 \\(\\Theta(\\log_d n)=\\Theta(\\log n/\\log d)\\)，insert 上滤更快，extract-min 每层要在 \\(d\\) 个孩子里找最小。Johnson 用它调最短路里堆的常数。缺口不是斐波那契堆，而是<strong>同一套堆序下改扇出</strong>。</p><p><span class="marginnote">数字实例：100 万元素，二叉堆高约 20 层，4 叉堆只有 10 层。insert 沿一条路上滤，快了一倍；extract-min 却要在每层 4 个孩子里挑最小，比较变多。高度省出来的和每层多付的，就是选 \\(d\\) 的权衡账。</span></p><p>无句柄的 decrease-key 要先找到元素，\\(\\Theta(n)\\)，堆的对数没有意义。索引堆：<code>pos[id]</code> 存堆数组下标，交换时两边更新。</p><p><span class="marginnote">初学者容易以为堆&quot;顺便&quot;支持任意查找。堆只保证父不大于子，兄弟之间毫无秩序；没有句柄就只能线性扫数组，\\(\\Theta(n)\\)，一切对数承诺随之作废。</span></p><p><span class="marginnote">\\(d=4\\) 在 cache 行上有时更好：一层孩子更连续。过大则下滤的线性扫吃掉高度收益。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数组表示不变，只改父子公式。上滤与父比；下滤在 \\(d\\) 个孩子中取最小再比。索引：对外 id 稳定，对内下标变；<code>swap</code> 必须维护 <code>pos</code>。</p>',11)),(t(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ID%5B%22%E5%85%83%E7%B4%A0%20id%22%5D%20--%3E%20POS%5B%22pos%5Bid%5D%20%E4%B8%8B%E6%A0%87%22%5D%0A%20%20POS%20--%3E%20ARR%5B%22%E5%A0%86%E6%95%B0%E7%BB%84%22%5D%0A%20%20ARR%20--%3E%20CH%5B%22d%20%E4%B8%AA%E5%AD%A9%E5%AD%90%E8%BF%9E%E7%BB%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=d("p",null,"建堆仍可自底向上 \\(\\Theta(n)\\)：每层工作与 \\(d\\) 有关，渐近仍线性。",-1)),a[4]||(a[4]=d("h2",{id:"机制",tabindex:"-1"},[r("机制 "),d("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=d("p",null,"Dijkstra 一类反复 decrease-key 的算法，合同必须提供句柄。二叉够用时不必上 \\(d\\)；只有剖析显示 extract 与 insert 比例极端，才调 \\(d\\)。这是常数与 cache 的事，不是新 ADT。",-1)),(t(),i(l,null,{default:e(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%89%87%E5%87%BA%20d%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20H%5B%22%E6%A0%91%E9%AB%98%20log_d%20n%20%E5%8F%98%E7%9F%AE%22%5D%0A%20%20D%20--%3E%20W%5B%22%E6%AF%8F%E5%B1%82%E5%AD%A9%E5%AD%90%E6%95%B0%E5%8F%98%E5%A4%9A%22%5D%0A%20%20H%20--%3E%20INS%5B%22insert%20%E4%B8%8A%E6%BB%A4%E6%9B%B4%E5%BF%AB%EF%BC%9A%E8%B5%B0%E7%9A%84%E5%B1%82%E6%95%B0%E5%8F%98%E5%B0%91%22%5D%0A%20%20W%20--%3E%20EXT%5B%22extract-min%20%E6%9B%B4%E6%85%A2%EF%BC%9A%E6%AF%8F%E5%B1%82%E8%A6%81%E6%89%AB%20d%20%E4%B8%AA%E5%AD%A9%E5%AD%90%E6%89%BE%E6%9C%80%E5%B0%8F%22%5D%0A%20%20INS%20--%3E%20BAL%5B%22d%20%E6%98%AF%E6%9D%83%E8%A1%A1%EF%BC%9A4%20%E9%99%84%E8%BF%91%E5%B8%B8%E6%98%AF%E7%94%9C%E7%82%B9%22%5D%0A%20%20EXT%20--%3E%20BAL%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">句柄可以类比行李票：行李（元素）在仓库里被搬来搬去（堆内交换），你手里的票（id→pos 映射）始终有效，凭票一查就知道它此刻在哪一格，不必翻遍仓库。</span></p><p>与 B+ 对照：堆不支持高效任意键查找与中序。索引只映射「已知 id」，不是字典。字典是下一课散列或回到树。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入二项堆、斐波那契摊还，不把操作系统就绪队列绑死为 \\(d\\) 叉。也不把 <code>pos</code> 数组写成必须全局 \\(n\\) 大——可用卫星指针反指堆槽。</p><p>后课默认：优先队列可以是二叉或 \\(d\\) 叉，decrease-key 靠句柄。无序键的期望常数查找靠散列函数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(d\\) 叉降低高度、加重每层比较；数组公式改孩子跨度。</li><li>索引堆维护 id→下标，decrease-key 才对数。</li><li>任意键期望 \\(O(1)\\) 是下一课 \\(h(k)\\)，不是堆。</li><li>出处：Williams, <em>CACM</em>, 1964（二叉）；Johnson, 1975；Cormen et al. 第 6 章。</li></ul>',7))])}const g=E(B,[["render",c]]);export{f as __pageData,g as default};
